<template><div class="editor-layout"><aside class="editor-sidebar"><div class="eyebrow">LOCAL CONTENT TOOL</div><h2>内容编辑器</h2><button v-for="tab in tabs" :key="tab" :class="{active:section===tab}" @click="section=tab">{{ tab }}</button><div class="editor-warning">仅开发环境开放。编辑器不会自动修改项目文件，请复制或导出 JSON 后手动替换 `src/data/site-content.json`。</div><button class="button secondary full" @click="reset">恢复初始数据</button></aside><section class="editor-main"><h1>{{ section }}</h1><template v-if="section==='网站与首页'"><label>网站名称<input v-model="draft.site.name"></label><label>英文名称<input v-model="draft.site.nameEn"></label><label>站点简介<input v-model="draft.site.description"></label><label>Logo 文字<input v-model="draft.site.logoText"></label><label>页脚文字<textarea v-model="draft.site.footerText"/></label><label>首页标题<input v-model="draft.home.title"></label><label>首页副标题<textarea v-model="draft.home.subtitle"/></label><label>搜索提示词<input v-model="draft.home.searchPlaceholder"/></label><label>热门关键词（逗号分隔）<input :value="draft.home.hotKeywords.join(',')" @input="draft.home.hotKeywords=$event.target.value.split(',').map(x=>x.trim()).filter(Boolean)"/></label></template><template v-else-if="section==='分类管理'"><div class="editor-list"><div v-for="(item,i) in draft.categories" :key="item.id" class="editor-list-item"><input v-model="item.name" placeholder="分类名称"><input v-model="item.description" placeholder="分类说明"><input v-model="item.icon" placeholder="图标"><select v-model="item.color"><option>blue</option><option>mint</option><option>orange</option><option>pink</option><option>purple</option></select><button class="danger" @click="removeCategory(i)">删除</button></div></div><button class="button secondary" @click="addCategory">＋ 新增分类</button></template><template v-else-if="section==='游戏管理'"><div class="editor-list"><div v-for="g in draft.games" :key="g.id" class="editor-list-item"><button @click="selectedId=g.id">{{ g.title || '未命名游戏' }}</button><small>{{ g.slug }}</small><button class="danger" @click="removeGame(g.id)">删除</button></div></div><button class="button secondary" @click="addGame">＋ 新增游戏</button><template v-if="selected"><hr><label>游戏名称<input v-model="selected.title"></label><label>网址标识<input v-model="selected.slug"></label><label>副标题<input v-model="selected.subtitle"></label><label>介绍<textarea v-model="selected.description"/></label><label>封面路径或 URL<input v-model="selected.cover" placeholder="/images/game.png 或 https://…"></label><GameCover class="editor-preview" :src="selected.cover" :title="selected.title"/><label>封面替代文字<input v-model="selected.coverAlt"></label><label>分类（可多选）<div class="checks"><label v-for="c in draft.categories" :key="c.id"><input type="checkbox" :checked="selected.categoryIds.includes(c.id)" @change="setCategory(c.id,$event.target.checked)">{{ c.name }}</label></div></label><label>标签（逗号分隔）<input :value="selected.tags.join(',')" @input="selected.tags=split($event.target.value)"></label><label>平台（逗号分隔）<input :value="selected.platforms.join(',')" @input="selected.platforms=split($event.target.value)"></label><label>开发者<input v-model="selected.developer"></label><label>版本<input v-model="selected.version"></label><label>游戏特色（每行一项）<textarea :value="selected.features.join('\n')" @input="selected.features=lines($event.target.value)"/></label><label>操作说明（每行一项）<textarea :value="selected.controls.join('\n')" @input="selected.controls=lines($event.target.value)"/></label><label>授权状态<select v-model="selected.licenseStatus"><option value="pending_review">待核实</option><option value="official_only">仅官方链接</option><option value="permission_confirmed">已确认分发权限</option></select></label><label>下载模式<select v-model="selected.downloadMode"><option value="info_only">仅展示信息</option><option value="official_link">官方链接</option><option value="authorized_hosted">本站网盘（需已确认授权）</option></select></label><label>来源链接<input v-model="selected.sourceUrl"></label><label>下载链接<input v-model="selected.downloadUrl"></label><label>授权说明<textarea v-model="selected.licenseNote"/></label><label><input type="checkbox" v-model="selected.recommended">精选推荐　<input type="checkbox" v-model="selected.published">公开发布</label></template></template><template v-else><p>攻略文章 {{ draft.guides.length }} 篇。可在 JSON 预览中查看并通过导入 JSON 更新文章章节、标签及关联游戏。</p><textarea class="import-box" v-model="guideJson"/><button class="button secondary" @click="importGuides">应用攻略 JSON</button></template></section><aside class="editor-preview-pane"><div class="preview-head"><div><b>JSON 实时预览</b><span :class="errors.length?'status-error':'status-ok'">{{ errors.length?`${errors.length} 项需修正`:'结构校验通过' }}</span></div><button class="button primary" :disabled="errors.length" @click="copy">复制完整 JSON</button></div><ul v-if="errors.length" class="error-list"><li v-for="e in errors" :key="e">{{ e }}</li></ul><textarea class="json-preview" :value="json" readonly/><div class="editor-actions"><button class="button secondary" :disabled="errors.length" @click="download">导出 JSON</button><label class="button secondary file-button">导入 JSON<input type="file" accept="application/json,.json" @change="importFile"></label></div><p class="editor-help">工作流：复制或导出 JSON → 打开 <code>src/data/site-content.json</code> → 替换并保存 → 重新运行或构建。此页面草稿仅保存在当前浏览器，不会写入源文件。</p><textarea v-model="pasteJson" class="import-box" placeholder="也可以粘贴 JSON 后导入"/><button class="button secondary" @click="importText">校验并导入粘贴内容</button></aside></div></template>
<script setup>
import{computed,ref,watch}from'vue';import seed from '../data/site-content.json';import{validateContent}from'../utils/content-validator';import GameCover from '../components/GameCover.vue'
const storageKey='fgd-editor-draft',initial=JSON.stringify(seed),draft=ref(load()),section=ref('网站与首页'),selectedId=ref(draft.value.games[0]?.id||''),tabs=['网站与首页','分类管理','游戏管理','攻略文章'],pasteJson=ref(''),guideJson=ref(JSON.stringify(draft.value.guides,null,2));function load(){try{return JSON.parse(localStorage.getItem(storageKey)||initial)}catch{return JSON.parse(initial)}}
const selected=computed(()=>draft.value.games.find(g=>g.id===selectedId.value)),json=computed(()=>JSON.stringify(draft.value,null,2)),errors=computed(()=>validateContent(draft.value));watch(draft,v=>localStorage.setItem(storageKey,JSON.stringify(v)),{deep:true});watch(()=>draft.value.guides,v=>guideJson.value=JSON.stringify(v,null,2),{deep:true})
function split(x){return x.split(',').map(y=>y.trim()).filter(Boolean)}function lines(x){return x.split('\n').map(y=>y.trim()).filter(Boolean)}function setCategory(id,on){selected.value.categoryIds=on?[...new Set([...selected.value.categoryIds,id])]:selected.value.categoryIds.filter(x=>x!==id)}function addCategory(){const n=draft.value.categories.length+1;draft.value.categories.push({id:`category-${Date.now()}`,name:`新分类 ${n}`,description:'补充分类说明',icon:'✦',color:'blue',sortOrder:n})}function removeCategory(i){const c=draft.value.categories[i],refs=draft.value.games.filter(g=>g.categoryIds.includes(c.id));if(refs.length&&!confirm(`该分类被以下游戏引用：${refs.map(g=>g.title).join('、')}。删除会移除这些引用，继续吗？`))return;draft.value.games.forEach(g=>g.categoryIds=g.categoryIds.filter(id=>id!==c.id));draft.value.categories.splice(i,1)}function addGame(){const id=`game-${Date.now()}`;draft.value.games.push({id,slug:id,title:'新游戏',subtitle:'补充简短介绍',description:'补充游戏介绍',cover:'',coverAlt:'游戏封面',screenshots:[],categoryIds:[],tags:[],platforms:[],releaseYear:null,developer:'',version:'',language:[],gameSize:'',recommended:false,published:false,licenseStatus:'pending_review',licenseNote:'授权情况待核实',licenseUrl:'',sourceUrl:'',downloadUrl:'',downloadMode:'info_only',downloadLabel:'',features:[],controls:[],requirements:[],faqs:[],relatedGameIds:[]});selectedId.value=id}function removeGame(id){if(!confirm('确定删除这条游戏内容？'))return;draft.value.games=draft.value.games.filter(g=>g.id!==id);draft.value.games.forEach(g=>g.relatedGameIds=g.relatedGameIds.filter(x=>x!==id));selectedId.value=draft.value.games[0]?.id||''}async function copy(){try{await navigator.clipboard.writeText(json.value);alert('JSON 已复制。请粘贴回 src/data/site-content.json。')}catch{document.querySelector('.json-preview').focus();document.querySelector('.json-preview').select()}}function download(){if(errors.value.length)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([json.value],{type:'application/json'}));a.download='site-content.json';a.click();URL.revokeObjectURL(a.href)}function useImported(text){try{const next=JSON.parse(text),issues=validateContent(next);if(issues.length){alert(issues.join('\n'));return}draft.value=next;selectedId.value=next.games?.[0]?.id||'';alert('JSON 校验通过并已导入浏览器草稿。')}catch(e){alert(`JSON 语法错误：${e.message}`)}}function importText(){useImported(pasteJson.value)}function importFile(e){const file=e.target.files?.[0];if(file){const reader=new FileReader();reader.onload=()=>useImported(String(reader.result));reader.readAsText(file)}e.target.value=''}function importGuides(){try{const arr=JSON.parse(guideJson.value);if(!Array.isArray(arr))throw Error('攻略内容需要是数组');draft.value.guides=arr}catch(e){alert(`无法应用：${e.message}`)}}function reset(){if(!confirm('恢复随项目提供的初始内容？浏览器中的编辑草稿将被覆盖。'))return;draft.value=JSON.parse(initial);selectedId.value=draft.value.games[0]?.id||'';localStorage.removeItem(storageKey)}
</script>
